"use client";

import React from "react";

import { InnerGlow } from "@/components/InnerGlow";

export default function Example() {
	return (
		<div className="h-screen w-full flex items-center justify-center relative overflow-hidden bg-black">
			<div className="grid relative mx-auto w-[300px] h-[300px] overflow-hidden bg-white rounded-md p-6 aspect-square place-items-center text-3xl font-medium">
				<InnerGlow />
				<p>Inner Glow</p>
			</div>{" "}
		</div>
	);
}

import { cn } from "@/lib/utils";

// Credit:
// https://starui.link/docs/components/inner-glow

// add to scss file
// @property --hue-rotation {
//   syntax: "<angle>";
//   initial-value: 0turn;
//   inherits: false;
// }

// @theme {
//   --animate-inner-glow: inner-glow 4s linear infinite;
//   @keyframes inner-glow {
//     from {
//       --hue-rotation: 0turn;
//     }
//     to {
//       --hue-rotation: 1turn;
//     }
//   }
// }
interface InnerGlowProps extends React.HTMLAttributes<HTMLDivElement> {}

function InnerGlow({ className, ...props }: InnerGlowProps) {
	return (
		<div
			className={cn(
				"absolute -inset-3 border-10 pointer-events-none blur-md [border-image:conic-gradient(from_var(--hue-rotation)_in_hsl_longer_hue,red-600,red-600)_1] animate-inner-glow",
				className
			)}
			{...props}
		/>
	);
}

export { InnerGlow };

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
